INSERT INTO "agent_decisions" VALUES(9,'f3060b6c-58db-4b73-88c5-a4d7d00b1f82','adhoc','seo',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-22-seo-title-ctr","reason":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: docs/playbooks/google-seo.md G1, data-quality-2026-11-22.md"}','{"design":{"audience_format":"site","control":"claude-bezkoshtovno, gemini-dlya-studentiv-bezkoshtovno, chomu-ne-pratsyuie-chatgpt, chatgpt-vs-gemini-vs-claude без змін","guardrail_metrics":"покази варіанта ≥ 0,8× бази","hypothesis":"На сторінках із ≥200 показами і позицією 5–9 CTR 0–1 % дає title, що обрізається й повторює ключ, та description без чіткої обіцянки. Коротший title (≤60 знаків до « | ШІкарно», відповідь або вигода на початку) і перший абзац-відповідь підіймуть CTR без втрати позиції.","kind":"metadata","max_share":1.0,"sample_size":8,"success_metric":"CTR сторінки в GSC, 28 днів після проти 28 днів до, різниця-в-різницях з контролем","threshold":"CTR варіанта ≥ +0,8 п.п. (і ≥ ×1,5) відносно приросту контролю, середня позиція варіанта не гірша на > 1,0","variant":"yak-vidklyuchyty-gemini, chatgpt-bezkoshtovno-v-ukraini, anthropic-ipo, yak-skachaty-chatgpt: title ≤60, description 140–160 з конкретикою, перший абзац-відповідь (коміт 6096092, 22.11 22:09Z)"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:14Z','2026-11-25T12:28:14Z','executed',NULL,NULL,NULL,NULL,'52d4d71781d1b0557ba62863e9fb812f8a726b26378e217f3d12001975814bee','6989834fb685d787c1e332af406dff88a19ee1dc65eb80518d8d060caad55091');
