INSERT INTO "agent_decisions" VALUES(15,'f9b3a056-124c-44c9-a8d2-8e8a970a813e','adhoc','cso',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-24-yt-related-cta-v2","reason":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: strategy.md §8 24.11 (yt-related-cta redesign), forecast-audit-2026-11-24.md §4"}','{"design":{"audience_format":"shorts→long","control":"ep82 (якщо Related поставлено до 26.11, інакше виключити) + ≤4 Shorts 30.11–4.12 з Related і outro без заклику (ep88, ep89, ep90 …; exp add --arm control після заливки)","end_date":"2026-12-04","guardrail_metrics":"avg_pct Short не нижче control −5 п.п.; довгі в рекламі (6-2a9ncHaz4, guide1) — лише RELATED_VIDEO","hypothesis":"Short із голосовим закликом в outro («…у відео під роликом») і Related video на довге тієї ж теми дає щонайменше вдвічі більший приріст RELATED_VIDEO цільового довгого на 1 000 переглядів, ніж Short із тим самим Related, але без голосового заклику (outro — питання в коментарі).","kind":"cta","max_share":1.0,"sample_size":4,"start_date":"2026-11-24","success_metric":"приріст RELATED_VIDEO цільового довгого за 7 днів після Short проти 7 днів до, на 1 000 переглядів Short, від моменту, коли поставлено Related","threshold":"≥ 2× контролю і ≥ 5 на 1 000","variant":"ep83–ep86 (26–29.11), уже залиті: голосовий заклик є (ASR vo.wav 24.11)"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:15Z','2026-11-25T12:28:15Z','executed',NULL,NULL,NULL,NULL,'8192e5ea729178d51bf681152ec06988e56817b7dc6cc1cdc42fbde4d285b8a3','4f44eaef0b7c4db8f41913610ac3df894acdae2cb19998d51c06786b65e56ff6');
INSERT INTO "agent_decisions" VALUES(16,'51f97284-81ef-4e49-8016-b687b1ac3d48','adhoc','cso',NULL,NULL,'rule','experiment','{"action":"start","design":{"audience_format":"shorts→long","control":"ep82 (якщо Related поставлено до 26.11, інакше виключити) + ≤4 Shorts 30.11–4.12 з Related і outro без заклику (ep88, ep89, ep90 …; exp add --arm control після заливки)","end_date":"2026-12-04","guardrail_metrics":"avg_pct Short не нижче control −5 п.п.; довгі в рекламі (6-2a9ncHaz4, guide1) — лише RELATED_VIDEO","hypothesis":"Short із голосовим закликом в outro («…у відео під роликом») і Related video на довге тієї ж теми дає щонайменше вдвічі більший приріст RELATED_VIDEO цільового довгого на 1 000 переглядів, ніж Short із тим самим Related, але без голосового заклику (outro — питання в коментарі).","kind":"cta","max_share":1.0,"sample_size":4,"start_date":"2026-11-24","success_metric":"приріст RELATED_VIDEO цільового довгого за 7 днів після Short проти 7 днів до, на 1 000 переглядів Short, від моменту, коли поставлено Related","threshold":"≥ 2× контролю і ≥ 5 на 1 000","variant":"ep83–ep86 (26–29.11), уже залиті: голосовий заклик є (ASR vo.wav 24.11)"},"experiment_id":"exp-2026-11-24-yt-related-cta-v2","note":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: старт 24.11 ~09:25Z, вердикт 13.12"}','{"control":["ep82_tier_kitchen"],"start_date":"2026-11-24","status":"running","variant":["ep83_moonlock_chesno","ep84_prof_logoped","ep85_tier_travel","ep86_prof_manikyur"]}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:15Z','2026-11-25T12:28:15Z','executed',NULL,NULL,NULL,NULL,'4f44eaef0b7c4db8f41913610ac3df894acdae2cb19998d51c06786b65e56ff6','d878b3a485427175e8e24f6a05ecc6cd6755aec2305c8a3dd3ad87f1403c8da5');
INSERT INTO "agent_decisions" VALUES(17,'89bcbe69-3d1e-4167-b027-94d3c7d998a9','adhoc','analyst',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-22-duration-list","reason":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: docs/research/forecast-audit-2026-11-22.md (урок 1), strategy.md §7 п.2"}','{"design":{"audience_format":"shorts sec/skills (особисті дані, безпека, налаштування)","control":"та сама категорія тем, ≤35 с, одна порада","guardrail_metrics":"% перегляду і підписки","hypothesis":"Для тем про дані/налаштування глядача Shorts-список на 45–55 с із лічильником (N пунктів) збирає не менше переглядів зі стрічки, ніж та сама тема, стиснута до ≤35 с; правило «≤35 с» — про одну думку, а не про секунди.","kind":"duration","max_share":0.3,"sample_size":12,"success_metric":"медіана 7-денних переглядів (snap на 7-й день) і частка SHORTS у traffic","threshold":"variant ≥ 0,9× control за медіаною переглядів і частка SHORTS ≥ 70 % → правило «≤35 с або список із лічильником»; variant < 0,7× control → лишаємо «≤35 с»","variant":"список 45–55 с, 5–7 пунктів, лічильник на екрані, гачок про «твоє» без назви релізу"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:15Z','2026-11-25T12:28:15Z','executed',NULL,NULL,NULL,NULL,'d878b3a485427175e8e24f6a05ecc6cd6755aec2305c8a3dd3ad87f1403c8da5','45664387b8b8fdd065361d71e213b94d31c1412b11ff4d3a15685e25404610f2');
INSERT INTO "agent_decisions" VALUES(18,'83e2b09d-4504-414b-b2d7-a955344db3e1','adhoc','cso',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-22-yt-search-title","reason":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: docs/playbooks/youtube.md E2"}','{"design":{"audience_format":"shorts","control":"Shorts того ж формату з назвою-хуком без запиту на початку","guardrail_metrics":"перегляди за 7 днів ≥ 0,9× control","hypothesis":"Shorts, чия назва починається з точного запиту так, як його набирають («який ШІ для…», «як вимкнути…», «чи безпечно…»), і де Байт вимовляє запит у перші 3 с, збирають за 28 днів у 1,5 раза більше переглядів з пошуку без втрат у стрічці.","kind":"metadata","sample_size":10,"success_metric":"YT_SEARCH за 28 днів (медіана)","threshold":"variant ≥ 1,5× control","variant":"назва = запит із підказок YouTube і Google, запит вимовлено в перші 3 с, у описі повторено двічі"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:15Z','2026-11-25T12:28:15Z','executed',NULL,NULL,NULL,NULL,'45664387b8b8fdd065361d71e213b94d31c1412b11ff4d3a15685e25404610f2','33e5ae68066d5726fe78909fc0ad3c4285fb50b54c9c4bf2304c55ccb0b93d62');
INSERT INTO "agent_decisions" VALUES(19,'7cd0c50f-735e-4963-b528-43a5a7356e61','adhoc','cso',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-22-yt-long-intro","reason":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: docs/playbooks/youtube.md E3, strategy.md §7 п.3"}','{"design":{"audience_format":"long","control":"медіана 10 попередніх довгих (avg_pct ≈22 %)","guardrail_metrics":"перегляди за 7 днів ≥ медіани control","hypothesis":"Довге відео, що в перші 15 с показує результат або відповідь з назви (без лого, привітання й «сьогодні ми поговоримо»), а далі йде розділами по 2–4 хв, утримає в 1,4 раза довше, ніж наші довгі відео досі.","kind":"format","sample_size":4,"success_metric":"avg_pct і AVD за 7 днів","threshold":"avg_pct ≥ 30 % (≈1,4× control) і AVD ≥ 3 хв","variant":"холодний старт із результатом, обіцянка назви за 15 с, розділи з таймкодами, у кінці заставка на наступне відео серії"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:15Z','2026-11-25T12:28:15Z','executed',NULL,NULL,NULL,NULL,'33e5ae68066d5726fe78909fc0ad3c4285fb50b54c9c4bf2304c55ccb0b93d62','92abfc7569b11c5f0f22e60b7fdcdbf8430321efaf5731dce48a4873f043c543');
INSERT INTO "agent_decisions" VALUES(20,'bf073b80-e4a9-443f-934c-d2a951dbd64a','adhoc','algo_researcher',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-22-yt-trailer-bridge","reason":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: docs/playbooks/youtube.md §4 П1, strategy.md §8 22.11"}','{"design":{"audience_format":"shorts→long","control":"самостійні Shorts того ж періоду з Related на довге іншої теми","guardrail_metrics":"перегляди Short за 7 днів ≥ 0,9× control; старт після E1 або в окремі тижні","hypothesis":"Short-трейлер довгого на ту саму тему (вже опублікованого або анонсованого; Short дає завершену думку, а не «дивись далі») переводить у довге більше глядачів, ніж самостійний Short, у якого лише Related на довге.","kind":"format","sample_size":6,"success_metric":"перегляди RELATED_VIDEO цільового довгого на 1 000 переглядів Short за 7 днів; підписки на 1 000","threshold":"variant ≥ 2× control (поріг у документах не зафіксовано — відновлено за E1; уточнити до старту)","variant":"Shorts тижня на тему довгого тижня (напр. 3 Shorts з одного тір-листа/гайду), Related на це довге"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:15Z','2026-11-25T12:28:15Z','executed',NULL,NULL,NULL,NULL,'92abfc7569b11c5f0f22e60b7fdcdbf8430321efaf5731dce48a4873f043c543','6603122ee5aec953802c798bfd341578f6e1379fadcb45c167fe692af896a7fe');
INSERT INTO "agent_decisions" VALUES(21,'05c29708-c2a6-4c13-a176-24fb07726fae','adhoc','algo_researcher',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-22-yt-compare-title","reason":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: docs/playbooks/youtube.md §4 П12, strategy.md §8 22.11"}','{"design":{"audience_format":"long","control":"пошукова назва того ж відео в тому ж A/B","guardrail_metrics":"перегляди з YT_SEARCH за 28 днів не нижче медіани довгих","hypothesis":"Назва-порівняння у 3 кроки («за 10 хв, 1 год і 24 год»), матч («X vs Y») або цінова драбина («$1 vs $100») створює прогалину цікавості й виграє у пошукової назви у вбудованому A/B YouTube.","kind":"metadata","max_share":1.0,"sample_size":4,"success_metric":"переможець A/B YouTube за часткою часу перегляду","threshold":"назва-порівняння виграє щонайменше в 3 з 4 (поріг у документах не зафіксовано — відновлено; уточнити до старту)","variant":"назва-порівняння / матч / цінова драбина у вбудованому A/B (Test & compare) на 4 довгих"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:15Z','2026-11-25T12:28:15Z','executed',NULL,NULL,NULL,NULL,'6603122ee5aec953802c798bfd341578f6e1379fadcb45c167fe692af896a7fe','2cb3c151bce69327dbf8138108f487c98c2a1cfb7cf5077ed0f1bf0d8e469203');
INSERT INTO "agent_decisions" VALUES(22,'d8e5aaae-f5e3-4afc-bfd1-13b1f2d8d3b9','adhoc','algo_researcher',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-23-yt-endscreen-named","reason":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: docs/playbooks/youtube.md §5.2, strategy.md §8 23.11"}','{"design":{"audience_format":"long","control":"13 довгих 22.10–20.11 (END_SCREEN 0, PLAYLIST 2)","guardrail_metrics":"AVD варіанта ≥ медіани контролю; утримання на останніх 30 с не нижче контролю більш ніж на 5 п.п.","hypothesis":"Довге, у якого в останні 20 с Байт голосом називає конкретне наступне відео і в Studio стоїть заставка з цим відео + плейлистом серії, дасть ≥15 переходів END_SCREEN+PLAYLIST на 1 000 переглядів довгого. У контролі 0.","kind":"cta","max_share":1.0,"sample_size":4,"success_metric":"перегляди END_SCREEN і PLAYLIST у traffic_daily цільового відео за 14 днів після виходу довгого / перегляди довгого","threshold":"≥15 на 1 000 за 14 днів і ненульове значення щонайменше в 3 з 4","variant":"гайд #1 (25.11), шоу #3 (29.11), гайд #2 (27.11 або 2.12), наступне довге"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:15Z','2026-11-25T12:28:15Z','executed',NULL,NULL,NULL,NULL,'2cb3c151bce69327dbf8138108f487c98c2a1cfb7cf5077ed0f1bf0d8e469203','0d62e0971811e596716f43443008a9baa22c663da350aeb5fff2ef5b9d2226e3');
INSERT INTO "agent_decisions" VALUES(23,'cf5f1ddf-802a-4690-be36-6e55f4c44a49','adhoc','seo',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-22-seo-firsthand","reason":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: docs/playbooks/google-seo.md G2"}','{"design":{"audience_format":"site","control":"6 найближчих за часом статей тієї ж рубрики без блоку","hypothesis":"Блок «Байт перевірив» (власний тест: що зробили, скрін, результат, дата, ціна в грн / чи доступно в Україні) робить статтю «не-комодіті»; такі статті за 14 днів отримують більше показів і кліків, ніж переказ новини.","kind":"format","sample_size":12,"success_metric":"медіана показів і кліків сторінки за перші 14 днів (site_pages за період)","threshold":"медіана показів варіанта ≥ 1,5× контролю і кліки ≥ контролю","variant":"6 нових статей-новин і гайдів з блоком «Байт перевірив», 2+ власні скріни"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:15Z','2026-11-25T12:28:15Z','executed',NULL,NULL,NULL,NULL,'0d62e0971811e596716f43443008a9baa22c663da350aeb5fff2ef5b9d2226e3','48818b9c77045292c62bad044520dc2e01ef0eb4ddd1b8bcc39f58cd3e095138');
INSERT INTO "agent_decisions" VALUES(24,'20b901b9-bfbf-4786-829b-99711a8ad28e','adhoc','seo',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-22-seo-hub-refresh","reason":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: docs/playbooks/google-seo.md G3, strategy.md §8 25.11 (designed, не стартував)"}','{"design":{"audience_format":"site","control":"gemini-skills-zamist-gems, claude-5-5-opus-sonnet-haiku, mono-keshbek-shi без змін","guardrail_metrics":"старт не раніше 1.12 (після core update), краще після December update","hypothesis":"Якщо сторінку з позицією 8–30 суттєво оновити (новий H2 під підзапит із GSC і таблицю) і поставити на неї 3+ внутрішні посилання з нових статей, вона підніметься в топ-5 і збере більше показів, ніж аналогічна сторінка без змін.","kind":"strategy","max_share":1.0,"sample_size":6,"success_metric":"зміна середньої позиції і показів, 28 днів після проти 28 днів до, різниця з контролем","threshold":"позиція варіанта покращилась ≥ 3 місця проти контролю, а покази ≥ ×1,3","variant":"shcho-take-shtuchnyi-intelekt, promty-dlya-chatgpt, claude-code-shcho-tse: суттєве оновлення, updated лише після реальної правки, 3+ нових внутрішніх посилань з анкором-запитом"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:15Z','2026-11-25T12:28:15Z','executed',NULL,NULL,NULL,NULL,'48818b9c77045292c62bad044520dc2e01ef0eb4ddd1b8bcc39f58cd3e095138','10099ef35b7fbbafef61f334065f316e9fac91c0d429794cc13b7c6f27b0a2f8');
INSERT INTO "agent_decisions" VALUES(25,'6b9c4a42-e5be-4514-803e-9d569282b7d5','adhoc','seo',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-22-tg-paid-seed","reason":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: docs/playbooks/telegram.md T1, docs/research/tg-paid-posts-2026-11-22.md"}','{"design":{"audience_format":"telegram","control":"органічний приріст за 14 днів до старту (база ≈ +2 на тиждень)","guardrail_metrics":"бюджет лише з рішення власника після 1.12","hypothesis":"2 куплені пости в українських ШІ-каналах із перетином аудиторії (@korysnosti, @AIGeniyUkr або @itest_ua), кожен з окремим інвайт-посиланням і ексклюзивом (PDF «50 промптів»), дадуть підписника дешевше за $0,5 і створять перетин аудиторій, через який ми з''явимося в «схожих каналах».","kind":"strategy","max_share":1.0,"sample_size":2,"success_metric":"ціна підписника (USD / приєднання за інвайтом) і частка тих, хто лишився через 7 днів","threshold":"≤ $0,5 за підписника, ≥ 80 % лишилися через 7 днів, з''являються приєднання не за інвайтами","variant":"2 пости в межах погодженого бюджету ($50–100, оплата через власника), старт ≥ 1.12"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:15Z','2026-11-25T12:28:15Z','executed',NULL,NULL,NULL,NULL,'10099ef35b7fbbafef61f334065f316e9fac91c0d429794cc13b7c6f27b0a2f8','4a0a32565b9dc3e694771e9254455713abf1e7a416fc13d4a4ada392e8baf904');
INSERT INTO "agent_decisions" VALUES(26,'bc03bca0-3fa4-417d-a61f-837ab34166c3','adhoc','seo',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-22-tg-site-iv","reason":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: docs/playbooks/telegram.md T3"}','{"design":{"audience_format":"site→telegram","control":"yak-skachaty-chatgpt, anthropic-ipo, yak-vidklyuchyty-gemini лише з поточним банером (свій інвайт на банер)","guardrail_metrics":"старт лише після закриття seo-title-ctr (ті самі сторінки)","hypothesis":"Читач сайту з Google, якому показали предметний блок «Цей промпт / чекліст повністю — у Telegram» усередині топ-статті (після «Коротко»), підпишеться частіше, ніж від верхнього банера PDF; IV-шаблон з channel додасть кнопку «Приєднатися».","kind":"cta","max_share":1.0,"sample_size":6,"success_metric":"приєднання за інвайтами на 1 000 кліків із Google (site_pages.clicks) за 28 днів","threshold":"у варіанта ≥ 2× контролю і ≥ 5 приєднань загалом","variant":"блок у тексті з окремим інвайтом на chatgpt-bezkoshtovno-v-ukraini, claude-bezkoshtovno, promty-dlya-chatgpt + IV-шаблон"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:15Z','2026-11-25T12:28:15Z','executed',NULL,NULL,NULL,NULL,'4a0a32565b9dc3e694771e9254455713abf1e7a416fc13d4a4ada392e8baf904','2928d8dccb68131aca22d7886ba46474db74aff799e85140cd106aed345a3124');
INSERT INTO "agent_decisions" VALUES(27,'b071530c-3ee6-49f6-98bd-7e9804f443e9','adhoc','cso',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-22-tt-search-caption","reason":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: docs/playbooks/tiktok.md T1"}','{"design":{"audience_format":"tiktok","control":"7 роликів 11–22.11 (поточний підпис), медіана 351","guardrail_metrics":"жодного зняття за спам чи Правила спільноти","hypothesis":"Перший рядок підпису = запит, як його набирають, плюс 3–5 варіантів «ші/ai/аі», плюс ключова фраза вбудованим текстом у перші 2 с підіймуть медіану переглядів за 7 днів у 1,5 раза завдяки пошуку.","kind":"metadata","sample_size":8,"success_metric":"медіана переглядів за 7 днів (tiktok_snap), дод. частка «Пошук» з TikTok Studio","threshold":"≥ 1,5× control (≥ 525)","variant":"підпис «<запит>\\n<2–3 варіанти запиту>\\n#штучнийінтелект #ші #нейромережі + 1 тематичний»; запит на екрані, Байт вимовляє"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:15Z','2026-11-25T12:28:15Z','executed',NULL,NULL,NULL,NULL,'2928d8dccb68131aca22d7886ba46474db74aff799e85140cd106aed345a3124','a25545ff2c94323d02a041acab827f32fa3101d9104032cf51f5134416385462');
INSERT INTO "agent_decisions" VALUES(28,'88807188-e17d-4fcd-ab2c-f3d6fa50e3db','adhoc','cso',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-22-tt-save-list","reason":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: docs/playbooks/tiktok.md T2"}','{"design":{"audience_format":"tiktok","control":"ролики того ж тижня без шпаргалки (новина або фішка)","guardrail_metrics":"лайки / перегляди не нижче control","hypothesis":"Ролик-чекліст «N кроків / N налаштувань» із фінальним кадром-шпаргалкою (2 с) і фразою «збережи, щоб не шукати» дасть ≥1 % збережень і більше охоплення.","kind":"cta","sample_size":6,"success_metric":"збереження / перегляди і медіана переглядів за 7 днів","threshold":"збереження ≥ 1 % і медіана переглядів ≥ 1,3× control","variant":"чекліст із фінальним кадром-шпаргалкою і голосовим «збережи»"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:15Z','2026-11-25T12:28:15Z','executed',NULL,NULL,NULL,NULL,'a25545ff2c94323d02a041acab827f32fa3101d9104032cf51f5134416385462','4904cf3c2bbaf8a3278d2692eddf88104155f7f46e8192dd3fd09e8944d6029d');
INSERT INTO "agent_decisions" VALUES(29,'392c7186-2b99-468a-88ba-1c5c083aa7c5','adhoc','cso',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-22-tt-long-test","reason":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: docs/playbooks/tiktok.md T3"}','{"design":{"audience_format":"tiktok","control":"короткі ролики того ж тижня (25–45 с)","guardrail_metrics":"не більше 30 % TikTok-слотів тижня","hypothesis":"Окрема TikTok-версія 60–90 с, де ШІ виконує живе завдання й результат видно на екрані, набере не менше переглядів, ніж наші 25–45-секундні; це відкриває Creator Rewards (>1 хв).","kind":"duration","max_share":0.3,"sample_size":6,"success_metric":"медіана переглядів за 7 днів; середній час перегляду з TikTok Studio","threshold":"≥ 1,0× медіани control і середній перегляд ≥ 25 с","variant":"60–90 с, результат ШІ на екрані з 0-ї секунди, вердикт Байта наприкінці"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:15Z','2026-11-25T12:28:15Z','executed',NULL,NULL,NULL,NULL,'4904cf3c2bbaf8a3278d2692eddf88104155f7f46e8192dd3fd09e8944d6029d','9a01e6ccdd5c9464b6e9f9b7232fc4725ed43cd1cc48db307ea399567532588c');
INSERT INTO "agent_decisions" VALUES(30,'795fdce3-d1b8-4897-919a-a68a3410a537','adhoc','platform_intel',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-24-ig-trial-reels","reason":"відновлено після рестарту 25.11 ~12:05Z (ops.sqlite стерто); джерело: docs/playbooks/instagram.md §4, strategy.md §8 24.11"}','{"design":{"audience_format":"instagram reels","control":"3 звичайні Reels того ж тижня (чергування через день), та сама обкладинка й шаблон кадру 0","guardrail_metrics":"0 позначок «неоригінальний» чи знять; підписники не падають; ліміт Trial Reels в API не перевищено","hypothesis":"Нові оригінальні Reels, опубліковані як Trial (SS_PERFORMANCE), за 72 год наберуть ≥2× медіани відтворень звичайних Reels того ж тижня.","kind":"format","max_share":0.5,"sample_size":6,"success_metric":"plays за 72 год (ig_snap), плюс skip_rate і avg_watched_pct","threshold":"медіана варіанта ≥ 2× контролю, skip_rate не гірший більш ніж на 5 п.п.","variant":"3 нові Reels 30.11–6.12 із trial_params, cover_url і новим кадром 0 (лише нові ролики)"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-25T12:28:15Z','2026-11-25T12:28:15Z','executed',NULL,NULL,NULL,NULL,'9a01e6ccdd5c9464b6e9f9b7232fc4725ed43cd1cc48db307ea399567532588c','661c085a501013163a1442a23746fc55d40ed409af139dc7fa2f90452cc4cd1c');
INSERT INTO "agent_decisions" VALUES(31,'90afbd57-9f62-4643-8c0f-b354eeda155f','restore-2026-11-25','cso',NULL,NULL,'restored','strategy_change','{"restored":true,"source":"docs/org/strategy.md §7","topic":"Плейбуки 22.11: рішення CSO"}','{"decisions":["Міст Short→довге — пріоритет №1 (E1 yt-related-cta): Related на кожному Short з 24.11","Shorts ≤35 с за замовчуванням; довше лише в duration-list; QA-гейт «≤35 с або exp-тег»","Довгі — холодний старт за 15 с і A/B 3 назв/обкладинок (E3 yt-long-intro)","Назва = пошуковий запит (E2 yt-search-title + T1 tt-search-caption); TikTok-підпис з запиту з 24.11","TikTok: 2 чеклісти зі шпаргалкою і 1–2 версії 60–90 с на тиждень (≤30 % слотів)"]}',NULL,NULL,NULL,NULL,NULL,NULL,'15393957b029',NULL,NULL,'2026-11-22T19:12:47Z','2026-11-22T19:12:47Z','decided',NULL,NULL,NULL,NULL,'661c085a501013163a1442a23746fc55d40ed409af139dc7fa2f90452cc4cd1c','edaad4736e7fcf8eb5e57db49c3f5e00261c09c4cd18fafa62f1fa15a978a8e0');
