INSERT INTO "agent_decisions" VALUES(52,'7ae813ea-89f0-4742-a52d-3b69acefede1','adhoc','coo',NULL,NULL,NULL,'strategy_change','data-quality 25.11: (1) v1 yt-related-cta running поряд з v2; (2) час встановлення Related не записується; (3) ep83–86 одночасно у frame0 і v2; (4) спільні цілі Related між групами v2 (ep85↔ep88/89 → M-KQwpDwpA4)','v1 закрито (pause). Related: власник пише боту «related готово» → CM записує ops decide (experiment, note related_set_at=<час повідомлення>) для кожного Short; без відповіді — related_set_at=null і Short виключається з v2. frame0: guardrail avg_pct рахувати лише по контролю/варіанту без v2-змішування, вердикт frame0 = CTR/перегляди перших 48 год (кадр 0 не залежить від outro). CSO 26.11: розвести Related ep88/ep89 на інше довге, ніж ep85.','docs/research/data-quality-2026-11-25.md',NULL,NULL,NULL,NULL,NULL,'67d1dfe36962',NULL,NULL,'2026-11-25T18:32:31Z','2026-11-25T18:32:31Z','executed',NULL,NULL,NULL,NULL,'9f3dd0b7da7880a51a223bdcd089aa839a2ed9b0a24d08c1ef807d44f2b7fe48','653cd1882646145fa461701d646bade30e80c26df1a92ff7565b547a9658ace6');
INSERT INTO "agent_decisions" VALUES(53,'66feec3f-8662-4f78-8321-4a76ca5cfe97','adhoc','coo',NULL,NULL,NULL,'prompt_change','COO 25.11 веч.: (1) run_voice.py: guide3 (~16 запитів) стояв перед ep88–90 (вихід 30.11–2.12) → ризик пропуску Short 30.11; (2) lake.py news: 10 пар однакових назв з різними URL; (3) growth_1201.jsonl без рядка за 24.11','(1) черга за датою виходу: weekly3 → ep88 → ep89 → ep90 → guide3; (2) дедуп назв за 30 днів у збирачі; (3) hq_data.py після 19Z сам знімає рядок росту. RUNBOOK: ЧЕРГА ОЗВУЧКИ, НОВИНИ БЕЗ ДУБЛІВ, ЗНІМОК РОСТУ — СТРАХОВКА','docs/research/data-quality-2026-11-25.md; studio/eps/run_voice.py; studio/data/growth_1201.jsonl',NULL,NULL,NULL,NULL,NULL,'67d1dfe36962',NULL,NULL,'2026-11-25T18:33:56Z','2026-11-25T18:33:56Z','executed',NULL,NULL,NULL,NULL,'653cd1882646145fa461701d646bade30e80c26df1a92ff7565b547a9658ace6','996fcb8ffacad4493b27d941a219e45198c29221b628ae2604c6886df74c3815');
INSERT INTO "agent_decisions" VALUES(54,'4c9c6f1a-6d90-4b35-80c6-6056879cda03','adhoc','coo',NULL,NULL,NULL,'prompt_change','{"change":"Дистрибуція IG/TikTok: «немає mp4» більше не причина пропуску. Джерело — власний YouTube Short: vidiq_video_upload(url=посилання на Short після public) → uploadId/videoUrl → vidiq_instagram_publish_reel / TikTok draft. Пропуск — лише після реальної помилки інструмента, і того ж дня рядок власнику у вечірньому звіті.","check":"HQ «Ліміти й пропуски»: Instagram і TikTok = ок щодня; 26.11 — Reel ep78 (догін) і ep83, TikTok ep83 після 17Z","evidence":"26.11 07:4xZ тест: vidiq_video_upload(url=youtube.com/shorts/Rlm1u-I6x00) → completed за ~2 хв, uploadId a6931f0f…","scope":"Менеджер дистрибуції (15:23 і 19:23 Київ), TikTok у час виходу; ep83–86 не мають локальних mp4","why":"Власник 25.11 20:46Z сам спитав «А в інсту сьогодні не лили? Забули?»: IG-відділ 13:24Z пропустив clip3 і ep78 через стертий рестартом ig.mp4, без повідомлення власнику; RUNBOOK уже допускав videoUrl = YouTube-посилання, але правило не застосували."}',NULL,NULL,NULL,NULL,0.9,NULL,NULL,'a88472ddf105',NULL,NULL,'2026-11-26T07:34:27Z','2026-11-26T07:34:27Z','decided',NULL,NULL,NULL,NULL,'996fcb8ffacad4493b27d941a219e45198c29221b628ae2604c6886df74c3815','b6a7f2b60ee55db8cc2fee46008743d364eff54fa9c806c04e168ac1b03f2a13');
INSERT INTO "agent_decisions" VALUES(55,'2f32d247-1db8-4919-b07a-264db205c206','adhoc','coo',NULL,NULL,NULL,'prompt_change','{"change":"Ліміт озвучки пояснюємо ДО питання власника: (1) HQ-блок «Ліміти й пропуски» з voice_log (успішні запити за 24 год, з якого часу 429, наступне вікно 10:02–10:52 Київ); (2) у вечірньому звіті COO — 1 рядок про озвучку, якщо був 429: скільки озвучено, що чекає, коли наступне вікно; (3) у розкладі HQ «Конвеєр дня» — рядок вікна TTS.","check":"Наступний 429 — власник бачить причину на HQ без питання; 0 питань «ліміти?» за тиждень","evidence":"studio/eps/voice_log.jsonl 25.11: tts_ok=19, STOP щогодини з 18:22Z","why":"Власник 25.11 20:49–20:56Z: «Зараз ти в лімітах знову?», «Ліміт живий на озвучку, ти ж нічого не робив». Факт: 25.11 використано 19 запитів (15 у вікні 08:02–08:53Z, 2 guide3 об 11Z, 2 weekly3 о 15Z і 18Z), далі щогодинні 429 — пояснення ніде не було видно."}',NULL,NULL,NULL,NULL,0.85,NULL,NULL,'a88472ddf105',NULL,NULL,'2026-11-26T07:34:28Z','2026-11-26T07:34:28Z','decided',NULL,NULL,NULL,NULL,'b6a7f2b60ee55db8cc2fee46008743d364eff54fa9c806c04e168ac1b03f2a13','bca4d8a47e18fd60ed9e60a2da816cfca820d218346c7b22bbe4247ad620903d');
INSERT INTO "agent_decisions" VALUES(56,'e879950d-8aef-43a4-9e48-ddbec7f78c06','adhoc','coo',NULL,NULL,NULL,'strategy_change','{"alternatives":"озвучити ep87 у вікні 26.11 після weekly3 — відкинуто: weekly3 потребує ≥10 запитів з переозвучками, лишку немає; 27.11 вікно — резерв weekly3/ep88","change":"ep87 (Чорна пʼятниця, ідея №34) знято з Shorts: TTS-слоти 26–27.11 — на шоу #3 (weekly3, 10 частин ще + переозвучки), далі ep88 (30.11). Тема Чорної пʼятниці вже покрита: 3 статті сайту (23.11, 26.11, 27.11), TG №142, №150. Сценарій і фактчек PASS лишаються в архіві на ЧП-2027 / кіберпонеділок не переносимо.","check":"weekly3 11/11 до 27.11 09:00Z; ep88 озвучено до 28.11","why":"Денний ліміт TTS ~15–19 запитів ковзний; шоу #3 — довгий (години YPP, must-have 400–500 год), 1/11 озвучено, вихід 29.11 12Z. Короткі новинні/перевірочні Shorts — медіана 45–48 переглядів (формат «перевірка»), після 27.11 тема неактуальна; 27.11 уже є 2 виходи (ep84 Short і гайд #2)."}',NULL,NULL,NULL,NULL,0.8,NULL,NULL,'a88472ddf105',NULL,NULL,'2026-11-26T07:34:28Z','2026-11-26T07:34:28Z','decided',NULL,NULL,NULL,NULL,'bca4d8a47e18fd60ed9e60a2da816cfca820d218346c7b22bbe4247ad620903d','f4ee2d0b3623e99768ecf2f7764bdb926aba17689d48728624bc1e3af6f9f65a');
