INSERT INTO "agent_decisions" VALUES(67,'df8e0a23-0108-4bf5-ba4e-2ad94feb851e','adhoc','platform_intel',NULL,NULL,'rule','experiment','{"action":"design","experiment_id":"exp-2026-11-27-tt-long-cut","reason":"Socialinsider 8,0 млн органічних TikTok I–VI.2026 (оновл. 11.11.2026): медіана 60–90 с 7 200 проти 30–60 с 2 200 і 15–30 с 1 000; наші 39 роликів усі 21–55 с; з 15.11 0 з 10 ≥1 000, плато за 36 год"}','{"design":{"audience_format":"tiktok","control":"копії Shorts (25–45 с), опубліковані в TikTok у ті самі дні 27.11–6.12, той самий шаблон підпису; базова лінія — медіана 10 роликів 15–25.11 (320, 0 з 10 ≥1 000)","guardrail_metrics":"жодного зняття/обмеження «неоригінальний контент» чи Правил спільноти; лайки/перегляди variant ≥ 0,7× control; середній час перегляду ≥ 25 с, якщо власник дасть TikTok Studio","hypothesis":"TikTok-нарізка 60–90 с із уже озвученого довгого (гайд #2, шоу #3, №186, №194), якої ще немає в TikTok, з найсильнішим твердженням у кадрі 0 і вшитими субтитрами, набирає за 72 год щонайменше вдвічі більше переглядів, ніж наші 25–45-секундні копії Shorts того ж тижня: довші ролики дають більше часу перегляду, а нарізка з довгого — оригінальний для TikTok файл (0 запитів TTS)","kind":"duration","max_share":0.3,"sample_size":4,"success_metric":"перегляди за 72 год (tiktok_snap, найближчий знімок ≥72 год від виходу), медіана variant / медіана control; додатково — кількість роликів ≥1 000 і збереження/перегляди","threshold":"медіана variant ≥ 2× медіани control (і ≥ 640) і щонайменше 1 з 4 ≥ 1 000 переглядів за 72 год","variant":"4 нарізки 60–90 с з довгих 27.11–6.12 (guide2 h5aUeuaD8OE, weekly3, rozbir186, guide194): кадр 0 = твердження-запит текстом + голос з 0-ї с, без розгону; підпис за T1 (запит у 1-му рядку, 1 тематичний + 1 нішевий хештег); мітка ШІ; без адрес на екрані; розрив ≥3 год від копії Short"},"status":"designed"}',NULL,NULL,NULL,1.0,NULL,NULL,'b458a819fcce',NULL,NULL,'2026-11-27T12:18:50Z','2026-11-27T12:18:50Z','executed',NULL,NULL,NULL,NULL,'d957105b4cef387bb31c31ffa65eb0262315b20445991b6726b3e8a05fb1433f','e808eecc3fa00b9e6f14635bf3c539eee6157aa21d966e89c751685de5edff32');
