INSERT INTO "experiments" VALUES('exp-2026-11-25-seo-no-aio-queries','platform_intel','Нові евергріни, головний запит яких без AI Overview у видачі (google.com.ua, uk, mobile) на момент написання, за 28 днів від першого показу мають вищий CTR і більше кліків, ніж евергріни під запити з AIO (Seer 24.04.2026: CTR 3,35% без AIO vs 0,94% не цитовано).','topic','4 нові евергріни слоту ''непокриті запити'', головний запит БЕЗ AIO (скрін видачі до написання)','4 нові евергріни того ж слоту/періоду, головний запит З AIO (поточний вибір за обсягом); чергування за порядком виходу','site/evergreen',NULL,NULL,8,0.5,'CTR сторінки в GSC (page x date) за 28 днів від першого показу; дод. кліки','CTR variant >= 2x control і кліки variant >= control','покази variant >= 0.5x control; G1/G3-сторінки не чіпати; G2-блок у обох плечах або в жодному','designed',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-22-frame0','designer','Новий кадр 0 Shorts (Frame0Host у Generic.tsx з коміту 2f94528: плашка бренду і серії, хук-питання на «ти» у 2 рядки, великий Байт по центру) дає більше «переглянули/гортали» у стрічці, ніж старий кадр 0 (заголовок + таблиця без Байта); вимірюємо проксі з API: перегляди за 48 год і частка SHORTS-трафіку','thumbnail','5 Shorts з FRAME0=True: ep82–ep86 (24–29.11)','10 попередніх Shorts зі старим кадром 0: ep71–ep77, ep79, ep80, ep81 (без ep78, cut6, довгих)','shorts','2026-11-24','2026-11-29',5,1.0,'частка SHORTS-трафіку і перегляди 48 год vs медіана контролю','+20% до медіани переглядів 48 год контролю і частка SHORTS ≥ контролю','avg_pct не нижче контролю −5 п.п. (avg_pct NULL, а не 0)','running',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-22-seo-title-ctr','seo','На сторінках із ≥200 показами і позицією 5–9 CTR 0–1 % дає title, що обрізається й повторює ключ, та description без чіткої обіцянки. Коротший title (≤60 знаків до « | ШІкарно», відповідь або вигода на початку) і перший абзац-відповідь підіймуть CTR без втрати позиції.','metadata','yak-vidklyuchyty-gemini, chatgpt-bezkoshtovno-v-ukraini, anthropic-ipo, yak-skachaty-chatgpt: title ≤60, description 140–160 з конкретикою, перший абзац-відповідь (коміт 6096092, 22.11 22:09Z)','claude-bezkoshtovno, gemini-dlya-studentiv-bezkoshtovno, chomu-ne-pratsyuie-chatgpt, chatgpt-vs-gemini-vs-claude без змін','site','2026-11-23',NULL,8,1.0,'CTR сторінки в GSC, 28 днів після проти 28 днів до, різниця-в-різницях з контролем','CTR варіанта ≥ +0,8 п.п. (і ≥ ×1,5) відносно приросту контролю, середня позиція варіанта не гірша на > 1,0','покази варіанта ≥ 0,8× бази','running',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-22-tg-specific-cta','seo','Вибір «А чи Б» плюс конкретний промпт і пряме посилання на PDF №37 у першому коментарі дадуть і відповіді під роликами, і переходи в Telegram, яких не дають питання без вибору.','cta','перші коментарі «А чи Б» + промпт + t.me/shikarno_ai_ua/37 під роликами 23–29.11: ep81, ep82, ep78, clip1, clip2','10 попередніх роликів (ep71…weekly2: 8 Shorts + weekly2, pryvatnist1), коментар — питання без вибору і без прямого посилання','yt_comment→telegram','2026-11-23',NULL,5,1.0,'(1) частка варіантних перших коментарів з відповіддю за 72 год; (2) перегляди поста №37 (?embed=1); (3) Δ учасників tg_daily','відповідь мають ≥3 варіантні коментарі, пост №37 ≥ +10 переглядів за тиждень, учасників ≥ +3','без прохань «перешли»; без платних постів і розіграшів','running',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-22-yt-related-cta','cso','Short із прив''язаним Related video і голосовим закликом Байта в останні 5 с («повна версія — посилання під назвою») переводить у довгі втричі більше глядачів, ніж Short лише з Related, без заклику.','cta','≤5 Shorts 30.11–6.12: Related на довге тієї ж теми + заклик голосом в останні 5 с (exp add після заливки)','ep82–ep86 (Related на гайд #1 без заклику, той самий FRAME0)','shorts→long','2026-11-30','2026-11-25',5,0.3,'перегляди RELATED_VIDEO на цільовому довгому на 1 000 переглядів Short за 7 днів','variant ≥ 2× control і ≥ 5 на 1 000','avg_pct Short не нижче control −5 п.п.','decided','Заморожено strategy_change CSO 24.11 (замінено на v2); дизайн суперечить фактам: контроль ep83–86 має голосовий заклик і різні Related (data-quality 25.11). Закрито без вердикту, щоб не змішувати з v2.','pause',NULL,'455bf0c4-3998-4df2-bf2e-59ef3d831a23');
INSERT INTO "experiments" VALUES('exp-2026-11-24-yt-related-cta-v2','cso','Short із голосовим закликом в outro («…у відео під роликом») і Related video на довге тієї ж теми дає щонайменше вдвічі більший приріст RELATED_VIDEO цільового довгого на 1 000 переглядів, ніж Short із тим самим Related, але без голосового заклику (outro — питання в коментарі).','cta','ep83–ep86 (26–29.11), уже залиті: голосовий заклик є (ASR vo.wav 24.11)','ep82 (якщо Related поставлено до 26.11, інакше виключити) + ≤4 Shorts 30.11–4.12 з Related і outro без заклику (ep88, ep89, ep90 …; exp add --arm control після заливки)','shorts→long','2026-11-24','2026-12-04',4,1.0,'приріст RELATED_VIDEO цільового довгого за 7 днів після Short проти 7 днів до, на 1 000 переглядів Short, від моменту, коли поставлено Related','≥ 2× контролю і ≥ 5 на 1 000','avg_pct Short не нижче control −5 п.п.; довгі в рекламі (6-2a9ncHaz4, guide1) — лише RELATED_VIDEO','running',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-22-duration-list','analyst','Для тем про дані/налаштування глядача Shorts-список на 45–55 с із лічильником (N пунктів) збирає не менше переглядів зі стрічки, ніж та сама тема, стиснута до ≤35 с; правило «≤35 с» — про одну думку, а не про секунди.','duration','список 45–55 с, 5–7 пунктів, лічильник на екрані, гачок про «твоє» без назви релізу','та сама категорія тем, ≤35 с, одна порада','shorts sec/skills (особисті дані, безпека, налаштування)',NULL,NULL,12,0.3,'медіана 7-денних переглядів (snap на 7-й день) і частка SHORTS у traffic','variant ≥ 0,9× control за медіаною переглядів і частка SHORTS ≥ 70 % → правило «≤35 с або список із лічильником»; variant < 0,7× control → лишаємо «≤35 с»','% перегляду і підписки','designed',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-22-yt-search-title','cso','Shorts, чия назва починається з точного запиту так, як його набирають («який ШІ для…», «як вимкнути…», «чи безпечно…»), і де Байт вимовляє запит у перші 3 с, збирають за 28 днів у 1,5 раза більше переглядів з пошуку без втрат у стрічці.','metadata','назва = запит із підказок YouTube і Google, запит вимовлено в перші 3 с, у описі повторено двічі','Shorts того ж формату з назвою-хуком без запиту на початку','shorts',NULL,NULL,10,0.3,'YT_SEARCH за 28 днів (медіана)','variant ≥ 1,5× control','перегляди за 7 днів ≥ 0,9× control','designed',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-22-yt-long-intro','cso','Довге відео, що в перші 15 с показує результат або відповідь з назви (без лого, привітання й «сьогодні ми поговоримо»), а далі йде розділами по 2–4 хв, утримає в 1,4 раза довше, ніж наші довгі відео досі.','format','холодний старт із результатом, обіцянка назви за 15 с, розділи з таймкодами, у кінці заставка на наступне відео серії','медіана 10 попередніх довгих (avg_pct ≈22 %)','long',NULL,NULL,4,0.3,'avg_pct і AVD за 7 днів','avg_pct ≥ 30 % (≈1,4× control) і AVD ≥ 3 хв','перегляди за 7 днів ≥ медіани control','designed',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-22-yt-trailer-bridge','algo_researcher','Short-трейлер довгого на ту саму тему (вже опублікованого або анонсованого; Short дає завершену думку, а не «дивись далі») переводить у довге більше глядачів, ніж самостійний Short, у якого лише Related на довге.','format','Shorts тижня на тему довгого тижня (напр. 3 Shorts з одного тір-листа/гайду), Related на це довге','самостійні Shorts того ж періоду з Related на довге іншої теми','shorts→long',NULL,NULL,6,0.3,'перегляди RELATED_VIDEO цільового довгого на 1 000 переглядів Short за 7 днів; підписки на 1 000','variant ≥ 2× control (поріг у документах не зафіксовано — відновлено за E1; уточнити до старту)','перегляди Short за 7 днів ≥ 0,9× control; старт після E1 або в окремі тижні','designed',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-22-yt-compare-title','algo_researcher','Назва-порівняння у 3 кроки («за 10 хв, 1 год і 24 год»), матч («X vs Y») або цінова драбина («$1 vs $100») створює прогалину цікавості й виграє у пошукової назви у вбудованому A/B YouTube.','metadata','назва-порівняння / матч / цінова драбина у вбудованому A/B (Test & compare) на 4 довгих','пошукова назва того ж відео в тому ж A/B','long',NULL,NULL,4,1.0,'переможець A/B YouTube за часткою часу перегляду','назва-порівняння виграє щонайменше в 3 з 4 (поріг у документах не зафіксовано — відновлено; уточнити до старту)','перегляди з YT_SEARCH за 28 днів не нижче медіани довгих','designed',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-23-yt-endscreen-named','algo_researcher','Довге, у якого в останні 20 с Байт голосом називає конкретне наступне відео і в Studio стоїть заставка з цим відео + плейлистом серії, дасть ≥15 переходів END_SCREEN+PLAYLIST на 1 000 переглядів довгого. У контролі 0.','cta','гайд #1 (25.11), шоу #3 (29.11), гайд #2 (27.11 або 2.12), наступне довге','13 довгих 22.10–20.11 (END_SCREEN 0, PLAYLIST 2)','long',NULL,NULL,4,1.0,'перегляди END_SCREEN і PLAYLIST у traffic_daily цільового відео за 14 днів після виходу довгого / перегляди довгого','≥15 на 1 000 за 14 днів і ненульове значення щонайменше в 3 з 4','AVD варіанта ≥ медіани контролю; утримання на останніх 30 с не нижче контролю більш ніж на 5 п.п.','designed',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-22-seo-firsthand','seo','Блок «Байт перевірив» (власний тест: що зробили, скрін, результат, дата, ціна в грн / чи доступно в Україні) робить статтю «не-комодіті»; такі статті за 14 днів отримують більше показів і кліків, ніж переказ новини.','format','6 нових статей-новин і гайдів з блоком «Байт перевірив», 2+ власні скріни','6 найближчих за часом статей тієї ж рубрики без блоку','site',NULL,NULL,12,0.3,'медіана показів і кліків сторінки за перші 14 днів (site_pages за період)','медіана показів варіанта ≥ 1,5× контролю і кліки ≥ контролю',NULL,'designed',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-22-seo-hub-refresh','seo','Якщо сторінку з позицією 8–30 суттєво оновити (новий H2 під підзапит із GSC і таблицю) і поставити на неї 3+ внутрішні посилання з нових статей, вона підніметься в топ-5 і збере більше показів, ніж аналогічна сторінка без змін.','strategy','shcho-take-shtuchnyi-intelekt, promty-dlya-chatgpt, claude-code-shcho-tse: суттєве оновлення, updated лише після реальної правки, 3+ нових внутрішніх посилань з анкором-запитом','gemini-skills-zamist-gems, claude-5-5-opus-sonnet-haiku, mono-keshbek-shi без змін','site',NULL,NULL,6,1.0,'зміна середньої позиції і показів, 28 днів після проти 28 днів до, різниця з контролем','позиція варіанта покращилась ≥ 3 місця проти контролю, а покази ≥ ×1,3','старт не раніше 1.12 (після core update), краще після December update','designed',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-22-tg-paid-seed','seo','2 куплені пости в українських ШІ-каналах із перетином аудиторії (@korysnosti, @AIGeniyUkr або @itest_ua), кожен з окремим інвайт-посиланням і ексклюзивом (PDF «50 промптів»), дадуть підписника дешевше за $0,5 і створять перетин аудиторій, через який ми з''явимося в «схожих каналах».','strategy','2 пости в межах погодженого бюджету ($50–100, оплата через власника), старт ≥ 1.12','органічний приріст за 14 днів до старту (база ≈ +2 на тиждень)','telegram',NULL,NULL,2,1.0,'ціна підписника (USD / приєднання за інвайтом) і частка тих, хто лишився через 7 днів','≤ $0,5 за підписника, ≥ 80 % лишилися через 7 днів, з''являються приєднання не за інвайтами','бюджет лише з рішення власника після 1.12','designed',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-22-tg-site-iv','seo','Читач сайту з Google, якому показали предметний блок «Цей промпт / чекліст повністю — у Telegram» усередині топ-статті (після «Коротко»), підпишеться частіше, ніж від верхнього банера PDF; IV-шаблон з channel додасть кнопку «Приєднатися».','cta','блок у тексті з окремим інвайтом на chatgpt-bezkoshtovno-v-ukraini, claude-bezkoshtovno, promty-dlya-chatgpt + IV-шаблон','yak-skachaty-chatgpt, anthropic-ipo, yak-vidklyuchyty-gemini лише з поточним банером (свій інвайт на банер)','site→telegram',NULL,NULL,6,1.0,'приєднання за інвайтами на 1 000 кліків із Google (site_pages.clicks) за 28 днів','у варіанта ≥ 2× контролю і ≥ 5 приєднань загалом','старт лише після закриття seo-title-ctr (ті самі сторінки)','designed',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-22-tt-search-caption','cso','Перший рядок підпису = запит, як його набирають, плюс 3–5 варіантів «ші/ai/аі», плюс ключова фраза вбудованим текстом у перші 2 с підіймуть медіану переглядів за 7 днів у 1,5 раза завдяки пошуку.','metadata','підпис «<запит>\n<2–3 варіанти запиту>\n#штучнийінтелект #ші #нейромережі + 1 тематичний»; запит на екрані, Байт вимовляє','7 роликів 11–22.11 (поточний підпис), медіана 351','tiktok','2026-11-27',NULL,8,0.3,'медіана переглядів за 7 днів (tiktok_snap), дод. частка «Пошук» з TikTok Studio','≥ 1,5× control (≥ 525)','жодного зняття за спам чи Правила спільноти','running',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-22-tt-save-list','cso','Ролик-чекліст «N кроків / N налаштувань» із фінальним кадром-шпаргалкою (2 с) і фразою «збережи, щоб не шукати» дасть ≥1 % збережень і більше охоплення.','cta','чекліст із фінальним кадром-шпаргалкою і голосовим «збережи»','ролики того ж тижня без шпаргалки (новина або фішка)','tiktok',NULL,NULL,6,0.3,'збереження / перегляди і медіана переглядів за 7 днів','збереження ≥ 1 % і медіана переглядів ≥ 1,3× control','лайки / перегляди не нижче control','designed',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-22-tt-long-test','cso','Окрема TikTok-версія 60–90 с, де ШІ виконує живе завдання й результат видно на екрані, набере не менше переглядів, ніж наші 25–45-секундні; це відкриває Creator Rewards (>1 хв).','duration','60–90 с, результат ШІ на екрані з 0-ї секунди, вердикт Байта наприкінці','короткі ролики того ж тижня (25–45 с)','tiktok',NULL,NULL,6,0.3,'медіана переглядів за 7 днів; середній час перегляду з TikTok Studio','≥ 1,0× медіани control і середній перегляд ≥ 25 с','не більше 30 % TikTok-слотів тижня','designed',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-24-ig-trial-reels','platform_intel','Нові оригінальні Reels, опубліковані як Trial (SS_PERFORMANCE), за 72 год наберуть ≥2× медіани відтворень звичайних Reels того ж тижня.','format','3 нові Reels 30.11–6.12 із trial_params, cover_url і новим кадром 0 (лише нові ролики)','3 звичайні Reels того ж тижня (чергування через день), та сама обкладинка й шаблон кадру 0','instagram reels',NULL,NULL,6,0.5,'plays за 72 год (ig_snap), плюс skip_rate і avg_watched_pct','медіана варіанта ≥ 2× контролю, skip_rate не гірший більш ніж на 5 п.п.','0 позначок «неоригінальний» чи знять; підписники не падають; ліміт Trial Reels в API не перевищено','designed',NULL,NULL,NULL,NULL);
INSERT INTO "experiments" VALUES('exp-2026-11-27-tt-long-cut','platform_intel','TikTok-нарізка 60–90 с із уже озвученого довгого (гайд #2, шоу #3, №186, №194), якої ще немає в TikTok, з найсильнішим твердженням у кадрі 0 і вшитими субтитрами, набирає за 72 год щонайменше вдвічі більше переглядів, ніж наші 25–45-секундні копії Shorts того ж тижня: довші ролики дають більше часу перегляду, а нарізка з довгого — оригінальний для TikTok файл (0 запитів TTS)','duration','4 нарізки 60–90 с з довгих 27.11–6.12 (guide2 h5aUeuaD8OE, weekly3, rozbir186, guide194): кадр 0 = твердження-запит текстом + голос з 0-ї с, без розгону; підпис за T1 (запит у 1-му рядку, 1 тематичний + 1 нішевий хештег); мітка ШІ; без адрес на екрані; розрив ≥3 год від копії Short','копії Shorts (25–45 с), опубліковані в TikTok у ті самі дні 27.11–6.12, той самий шаблон підпису; базова лінія — медіана 10 роликів 15–25.11 (320, 0 з 10 ≥1 000)','tiktok',NULL,NULL,4,0.3,'перегляди за 72 год (tiktok_snap, найближчий знімок ≥72 год від виходу), медіана variant / медіана control; додатково — кількість роликів ≥1 000 і збереження/перегляди','медіана variant ≥ 2× медіани control (і ≥ 640) і щонайменше 1 з 4 ≥ 1 000 переглядів за 72 год','жодного зняття/обмеження «неоригінальний контент» чи Правил спільноти; лайки/перегляди variant ≥ 0,7× control; середній час перегляду ≥ 25 с, якщо власник дасть TikTok Studio','designed',NULL,NULL,NULL,NULL);
